ALTER TABLE library_settings ADD COLUMN maximum_active_loans integer NOT NULL DEFAULT 3 CHECK(maximum_active_loans BETWEEN 1 AND 100),ADD COLUMN grace_period_days integer NOT NULL DEFAULT 0 CHECK(grace_period_days BETWEEN 0 AND 30),ADD COLUMN allow_borrowing_with_overdue boolean NOT NULL DEFAULT false;
CREATE TABLE library_borrowing_policies(school_id uuid NOT NULL REFERENCES schools(id),patron_type varchar(20) NOT NULL CHECK(patron_type IN('student','teacher','employee')),enabled boolean NOT NULL DEFAULT false,maximum_active_loans integer NOT NULL CHECK(maximum_active_loans BETWEEN 1 AND 100),loan_period_days integer NOT NULL CHECK(loan_period_days BETWEEN 1 AND 365),maximum_renewals integer NOT NULL CHECK(maximum_renewals BETWEEN 0 AND 20),grace_period_days integer NOT NULL CHECK(grace_period_days BETWEEN 0 AND 30),allow_borrowing_with_overdue boolean NOT NULL DEFAULT false,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(school_id,patron_type));
INSERT INTO library_borrowing_policies(school_id,patron_type,enabled,maximum_active_loans,loan_period_days,maximum_renewals,grace_period_days,allow_borrowing_with_overdue) SELECT school_id,kind,false,maximum_active_loans,default_loan_days,maximum_renewals,grace_period_days,allow_borrowing_with_overdue FROM library_settings CROSS JOIN(VALUES('student'),('teacher'),('employee'))k(kind) ON CONFLICT DO NOTHING;
